query:
PREFIX agents: <https://data.oireachtas.ie/ontology#>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>
SELECT DISTINCT ?member ?name WHERE {
 GRAPH ?g { ?member a agents:Member; foaf:name ?name . FILTER(STR(?name) = "Brendan Griffin") }
 FILTER(STRSTARTS(STR(?g), "https://data.oireachtas.ie/graph/member/"))
} ORDER BY ?member
